	@Test
	void pinnedRowsSurviveLruPressureAndOwnerClose() throws Exception {
		try (Fixture fixture = new Fixture()) {
			AtomicInteger opens = new AtomicInteger();
			try (MemoOwner owner = fixture.memo(fixture.countedRows(opens))) {
				assertThat(fixture.drain(owner.memo, fixture.row)).isEqualTo(2);
				RowState other = fixture.row.fork();
				try (RowCursor pinned = owner.memo.open(fixture.row)) {
					assertThat(pinned.next()).isTrue();
					for (int i = 0; i < 256; i++) {
						other.replaceSlot(0, fixture.add(SimpleValueFactory.getInstance().createLiteral("key-" + i)));
						assertThat(fixture.drain(owner.memo, other)).isEqualTo(2);
						assertThat(fixture.manager.usedBytes()).isLessThanOrEqualTo(512L << 10);
					}
					owner.memo.close();
					assertThat(pinned.next()).isTrue();
					assertThat(pinned.next()).isFalse();
				} finally {
					other.closeDecodedInputs();
				}
			}
		}
	}

